def check_mcqos_correctness(job, mode):
    if mode == 'LO':
        return job.finish_time <= job.deadline
    elif mode == 'HI':
        if job.task in T_HI:
            return job.finish_time <= job.deadline
        elif job.task in T_QOS:
            return job.finish_time <= job.deadline + L_bound
    return False

def edf_vd_preprocess(U_LO, U_LO_HI, U_HI_HI):
    x = U_LO_HI / (1 - U_LO)
    if x * U_LO + U_HI_HI <= 1:
        return x
    else:
        return None

def edf_vds_hi_mode(current_time, T_HI, T_QOS_tasks, T_server):
    if current_time >= t_2:
        # Schedule HI tasks and the Server Task using EDF
        ready_queue = sorted(T_HI + [ServerTask(T_server, U_QOS * T_server)], key=lambda x: x.deadline)
        active_task = ready_queue[0]
        if isinstance(active_task, ServerTask):
            run_qos_job(T_QOS_tasks)
        else:
            run_hi_job(active_task)

def get_min_supply(delta, U_QOS, T_QOS, starts_at_t2=False):
    blackout = (1 - U_QOS) * T_QOS
    if starts_at_t2:
        return max(0, (delta - blackout) * U_QOS)
    else:
        return max(0, (delta - 2 * blackout) * U_QOS)
